window.SCHOOL_LISTENING={"../assets/media/7079f09bb5acbf9614d0cde3df288abc84dc96c1999bbb65d860f9fe9b211fa6.mp3":[{"id":"PPT_7079f09bb5acbf96","audioId":"PPT_7079f09bb5acbf96","title":"Book 3 · Unit 2 · RW · READING 1","subtitle":"READING 1 · source slide 41","duration":277.6,"cues":[{"start":0,"end":1.82,"text":"Our changing planet.","coverage":1},{"start":3.16,"end":9.88,"text":"The Uppsala Glacier in Argentina used to be one of the biggest glaciers in South America.","coverage":1},{"start":10.64,"end":14.58,"text":"In 1928, it was covered in ice and snow.","coverage":1},{"start":15.08,"end":21.14,"text":"But now, the glacier is melting at an annual rate of about 200 meters,","coverage":1},{"start":21.78,"end":24.18,"text":"so the area is covered in water.","coverage":1},{"start":24.94,"end":27.78,"text":"This is evidence of global warming.","coverage":1},{"start":28.74,"end":30.34,"text":"Since 1900,","coverage":1},{"start":30.82,"end":35.4,"text":"the global temperature has gone up by around one degree centigrade.","coverage":1},{"start":36.38,"end":38.24,"text":"This may not sound like much,","coverage":1},{"start":38.72,"end":48.02,"text":"but such a small increase is causing sea levels to rise and threatening the habitat of many species of plants and animals.","coverage":1},{"start":49.14,"end":59.04,"text":"An increase of two degrees centigrade in global temperatures could result in extinction for 30 % of the world's land species.","coverage":1},{"start":60.5,"end":66.16,"text":"The Northwest Passage is a sea route which runs along the northern coast of Canada,","coverage":1},{"start":66.7,"end":69.38,"text":"between the Atlantic and Pacific Oceans.","coverage":1},{"start":70.38,"end":75.68,"text":"In the past, it was often difficult to use because the water was frozen.","coverage":1},{"start":76.58,"end":77.06,"text":"However,","coverage":1},{"start":77.64,"end":85.4,"text":"increasing temperatures and the subsequent deglaciation have made it easier for ships to travel through this route.","coverage":1},{"start":86.42,"end":95.88,"text":"The trouble is that the melting of the ice is leading to loss of habitat for the polar bears and other species which live in this area.","coverage":1},{"start":97.22,"end":102.38,"text":"Experts predict that global sea levels could rise by 30 .five","coverage":1},{"start":102.38,"end":107.06,"text":"to 122 centimeters by the end of the century.","coverage":1},{"start":108.18,"end":109.06,"text":"Consequently,","coverage":1},{"start":109.64,"end":114.88,"text":"some areas that were land a few hundred years ago are now underwater,","coverage":1},{"start":115.66,"end":120.08,"text":"and many low -lying islands may be underwater in the future.","coverage":1},{"start":121.14,"end":123.78,"text":"As a result of the changing climate,","coverage":1},{"start":124.34,"end":129.38,"text":"the world's ecosystems are also changing faster than ever before.","coverage":1},{"start":130.32,"end":141.14,"text":"More than one -third of the world's mangrove forests and around 50 % of the world's reefs have been destroyed in the last few decades.","coverage":1},{"start":142.08,"end":150.68,"text":"Forests are being cut down to provide land for food because human population is growing at such a rapid rate.","coverage":1},{"start":151.88,"end":156.84,"text":"38 % of the land on Earth is now used for growing food.","coverage":1},{"start":157.82,"end":167,"text":"As a result of the higher temperatures and higher levels of carbon dioxide in the atmosphere, plants are producing more pollen,","coverage":1},{"start":167.6,"end":170.32,"text":"which could lead to more cases of asthma,","coverage":1},{"start":170.82,"end":173.98,"text":"a medical condition which makes it hard to breathe.","coverage":1},{"start":175.3,"end":177.72,"text":"What is causing climate change?","coverage":1},{"start":178.58,"end":182.34,"text":"The main cause is the huge amount of greenhouse gases,","coverage":1},{"start":182.76,"end":185.46,"text":"such as methane and carbon dioxide,","coverage":1},{"start":185.94,"end":187.8,"text":"CO2, in the atmosphere.","coverage":1},{"start":188.5,"end":192,"text":"But the reason for this is the world's population,","coverage":1},{"start":192.56,"end":193.68,"text":"you and me.","coverage":1},{"start":194.08,"end":196.5,"text":"As the population increases,","coverage":1},{"start":196.82,"end":200.6,"text":"more land is needed to provide food and energy.","coverage":1},{"start":201.34,"end":203.68,"text":"Burning fossil fuels for heating,","coverage":1},{"start":204.12,"end":204.38,"text":"lighting,","coverage":1},{"start":205.18,"end":205.52,"text":"transport,","coverage":1},{"start":206.26,"end":206.7,"text":"electricity,","coverage":1},{"start":207.16,"end":210.66,"text":"or manufacturing produces carbon dioxide.","coverage":1},{"start":211.7,"end":212.26,"text":"Furthermore,","coverage":1},{"start":212.98,"end":215.42,"text":"humans breathe out carbon dioxide,","coverage":1},{"start":215.88,"end":220.7,"text":"while trees breathe in carbon dioxide and produce oxygen.","coverage":1},{"start":221.46,"end":223.12,"text":"So by cutting down trees,","coverage":1},{"start":223.52,"end":230.48,"text":"we are increasing the amount of carbon dioxide in the atmosphere and reducing the amount of oxygen.","coverage":1},{"start":231.58,"end":233.68,"text":"As a result of human activities,","coverage":1},{"start":234.36,"end":240.56,"text":"carbon dioxide levels are now at their highest in 800 ,000 years.","coverage":1},{"start":241.62,"end":247.18,"text":"The biggest challenge we all face is to prevent further environmental disasters.","coverage":1},{"start":247.7,"end":251.38,"text":"We must do something before it is too late.","coverage":1},{"start":252.2,"end":256.46,"text":"We need to reduce the amount of carbon dioxide in the atmosphere.","coverage":1},{"start":257.46,"end":262.52,"text":"We need to stop burning fossil fuels and start using renewable energy.","coverage":1},{"start":262.86,"end":266.54,"text":"We can get enough energy from renewable fuels,","coverage":1},{"start":266.94,"end":268.38,"text":"such as solar energy,","coverage":1},{"start":268.88,"end":270.2,"text":"hydroelectric energy,","coverage":1},{"start":270.5,"end":271.6,"text":"or wind power,","coverage":1},{"start":272.14,"end":275.72,"text":"to be able to stop using fossil fuels completely.","coverage":1}],"file":"4c559e8c4011b7f6055d.js","track":0,"media":"../assets/media/7079f09bb5acbf9614d0cde3df288abc84dc96c1999bbb65d860f9fe9b211fa6.mp3"}],"../assets/media/9131fd9edb3606080fec38f33f408385d0770f7cbc8d8cd2e7f31aed63d53a6f.mp3":[{"id":"PPT_9131fd9edb360608","audioId":"PPT_9131fd9edb360608","title":"Book 3 · Unit 2 · RW · READING 2","subtitle":"READING 2 · source slide 118","duration":228.1,"cues":[{"start":0,"end":3,"text":"The Causes and Effects of Deforestation","coverage":1},{"start":4.04,"end":7.86,"text":"Forests, which cover almost one -third of the surface of the Earth,","coverage":1},{"start":8.32,"end":11.16,"text":"produce oxygen and provide homes to plants,","coverage":1},{"start":11.52,"end":12.66,"text":"animals, and humans.","coverage":1},{"start":13.36,"end":14.14,"text":"These days,","coverage":1},{"start":14.5,"end":18.48,"text":"many of the world's great forests are threatened by deforestation,","coverage":1},{"start":19.1,"end":22.62,"text":"the process of removing trees from large areas of land.","coverage":1},{"start":23.68,"end":27,"text":"The destruction of forests occurs for several reasons.","coverage":1},{"start":27,"end":30.38,"text":"Trees are used as fuel or for construction,","coverage":1},{"start":31.32,"end":36.04,"text":"and cleared land is used as pasture for animals or fields for planting food.","coverage":1},{"start":36.86,"end":43.28,"text":"The main harmful effects of deforestation are climate change and damage to animal habitats.","coverage":1},{"start":45.06,"end":51.88,"text":"The main causes of deforestation are commercial farming by big business and farming by local people.","coverage":1},{"start":51.88,"end":57.82,"text":"Huge commercial farms have taken over large areas of forest in many countries.","coverage":1},{"start":58.74,"end":60.36,"text":"In Indonesia, for example,","coverage":1},{"start":61,"end":66.36,"text":"industrial logging is carried out to clear huge areas for the production of palm oil,","coverage":1},{"start":66.86,"end":67.84,"text":"while in Brazil,","coverage":1},{"start":68.56,"end":74.72,"text":"large areas of the Amazon rainforest are cleared to grow soy and produce vegetable oil.","coverage":1},{"start":75.4,"end":78.52,"text":"Local farmers also cut down and burn trees,","coverage":1},{"start":78.96,"end":83.18,"text":"but they clear areas just big enough to graze cattle or grow crops.","coverage":1},{"start":83.88,"end":84.32,"text":"However,","coverage":1},{"start":84.88,"end":86.3,"text":"after two or three years,","coverage":1},{"start":86.66,"end":87.38,"text":"the land can","coverage":1},{"start":87.38,"end":87.66,"text":"no","coverage":1},{"start":87.66,"end":88.78,"text":"longer be used,","coverage":1},{"start":89.1,"end":91.72,"text":"so the farmer moves to another piece of land.","coverage":1},{"start":92.56,"end":98.44,"text":"Normally, it takes around ten years for cleared land to recover, but in populated areas,","coverage":1},{"start":98.84,"end":101.06,"text":"the land is never allowed to recover.","coverage":1},{"start":101.06,"end":105.48,"text":"This constant reuse of land leads to heavy erosion,","coverage":1},{"start":106.18,"end":110.1,"text":"the loss of the top layer of soil which protects the ground.","coverage":1},{"start":111.02,"end":112.4,"text":"Erosion, in turn,","coverage":1},{"start":112.84,"end":115.1,"text":"can cause flooding and heavy rain.","coverage":1},{"start":116.56,"end":120.48,"text":"One serious effect of deforestation is climate change.","coverage":1},{"start":121.44,"end":127.38,"text":"Normally, tropical rainforests help control the Earth's temperature by absorbing carbon dioxide.","coverage":1},{"start":127.38,"end":128.5,"text":"However,","coverage":1},{"start":128.9,"end":129.44,"text":"recently,","coverage":1},{"start":129.96,"end":133.64,"text":"the Amazon area, where much of the world's rainforests are found,","coverage":1},{"start":134.06,"end":137.62,"text":"has been releasing more carbon dioxide than it absorbs.","coverage":1},{"start":138.64,"end":139.3,"text":"In addition,","coverage":1},{"start":139.76,"end":142.52,"text":"in areas where deforestation has taken place,","coverage":1},{"start":142.94,"end":149.74,"text":"the carbon dioxide goes into the atmosphere and traps heat in a process called the greenhouse effect.","coverage":1},{"start":150.5,"end":152.78,"text":"The result is global warming.","coverage":1},{"start":153.54,"end":156.64,"text":"Increasing global temperatures result in less rain.","coverage":1},{"start":156.64,"end":161.6,"text":"This causes the rainforests to dry out and leads to fires,","coverage":1},{"start":162.14,"end":165,"text":"which cause more emissions of carbon dioxide.","coverage":1},{"start":165.98,"end":172.84,"text":"In this way, the rainforests actually contribute to global warming instead of helping to solve it.","coverage":1},{"start":174.58,"end":178.3,"text":"Forest destruction also has an effect on biodiversity.","coverage":1},{"start":179.3,"end":186.44,"text":"Deforestation causes the loss of habitats and damage to land where plants and animal species live,","coverage":1},{"start":186.84,"end":189.56,"text":"leading to the extinction of many species.","coverage":1},{"start":190.5,"end":198.4,"text":"A decrease in biodiversity threatens entire ecosystems and destroys future sources of food and medicine.","coverage":1},{"start":199.88,"end":200.74,"text":"In conclusion,","coverage":1},{"start":201.48,"end":208.2,"text":"damage to the world's forests is leading to changes in the natural environment and causing global warming.","coverage":1},{"start":208.3,"end":210.4,"text":"Looking to the future,","coverage":1},{"start":210.92,"end":217.9,"text":"governments should act to plant more trees which will absorb carbon dioxide and protect forests from illegal logging.","coverage":1},{"start":218.8,"end":219.44,"text":"Otherwise,","coverage":1},{"start":220,"end":226.14,"text":"deforestation on such a large scale is sure to have terrible effects on the environment.","coverage":1}],"file":"6ee776d3e4858327f732.js","track":0,"media":"../assets/media/9131fd9edb3606080fec38f33f408385d0770f7cbc8d8cd2e7f31aed63d53a6f.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"Can you name any of the Seven Natural Wonders of the World?Possible answer: Examples from the answer booklet include the Grand Canyon, the Great Barrier Reef, Mount Everest and Victoria Falls.","slide":4,"shape":"18","bookPage":"38"},{"text":"What are some important geographical features, like mountains or rivers, in your country?Possible answer: In China, examples include the Yangtze River and the Himalayas.","slide":4,"shape":"20","bookPage":"38"},{"text":"What street or place names in your city or country refer to geography?Possible answer: Examples include River Road, Mountainview Drive and Canyon Drive.","slide":5,"shape":"19","bookPage":"38"},{"text":"Where do you think these places are located — Europe, the USA or Japan?Possible answer: The places are in the USA.","slide":7,"shape":"29","bookPage":"38"},{"text":"How old do you think these places are?Possible answer: The landscapes formed over millions of years; some of the rocks described are almost two billion years old.","slide":7,"shape":"30","bookPage":"38"},{"text":"What do you think formed these landscapes over time?Possible answer: Water shaped these landscapes over time. In Yosemite, frozen water in glaciers also played a part.","slide":7,"shape":"31","bookPage":"38"},{"text":"1  The river runs between the steep sides of a canyon.","slide":14,"shape":"7","bookPage":"38"},{"text":"2  A cavern is a very large cave.","slide":14,"shape":"8","bookPage":"38"},{"text":"3  Water and wind can form different shapes in rock.","slide":14,"shape":"9","bookPage":"38"},{"text":"4  The view from the mountain was spectacular.","slide":14,"shape":"10","bookPage":"38"},{"text":"5  A glacier is a slow-moving mass of ice.","slide":14,"shape":"11","bookPage":"38"},{"text":"a  The weather in the Grand Canyon can change very quickly.  Order: 3","slide":17,"shape":"6","bookPage":"39"},{"text":"b  Water is still changing the inside of Carlsbad Caverns.  Order: 4","slide":17,"shape":"7","bookPage":"39"},{"text":"c  Half Dome in Yosemite National Park was made by glaciers.  Order: 5","slide":17,"shape":"8","bookPage":"39"},{"text":"d  The Colorado River formed the Grand Canyon.  Order: 1","slide":17,"shape":"9","bookPage":"39"},{"text":"e  The rocks in the Grand Canyon are very old.  Order: 2","slide":17,"shape":"10","bookPage":"39"},{"text":"f  Yosemite Falls is the tallest waterfall in North America.  Order: 6","slide":17,"shape":"11","bookPage":"39"},{"text":"1  The Grand Canyon was formed in a few million years.","slide":20,"shape":"6","bookPage":"39"},{"text":"2  Some of the rocks in the Grand Canyon are half as old as the Earth.","slide":20,"shape":"8","bookPage":"39"},{"text":"3  The Carlsbad Caverns is the largest cave system in North America.","slide":20,"shape":"10","bookPage":"39"},{"text":"4  The water in Yosemite National Park comes from snow.","slide":20,"shape":"12","bookPage":"39"},{"text":"How might water change the Earth’s geography in the next 100 years?Possible answer: Water may continue to shape valleys and coastlines. Rising water levels could flood some low-lying areas.","slide":22,"shape":"18","bookPage":"39"},{"text":"Do you think that glaciers will ever return to where you live?Possible answer: Where I live, I think this is unlikely because the climate is too warm for glaciers.","slide":22,"shape":"20","bookPage":"39"},{"text":"Who should protect special natural areas in the world?Possible answer: Governments, businesses and individuals should all help. Governments can protect areas, businesses can reduce damage, and visitors can follow conservation rules.","slide":23,"shape":"19","bookPage":"39"},{"text":"a a gas which makes the air around the Earth warmer Correct answer: greenhouse gas","slide":36,"shape":"15","bookPage":"40"},{"text":"b someone or something that makes something happen Correct answer: cause","slide":36,"shape":"17","bookPage":"40"},{"text":"c the layer of gases around the Earth Correct answer: atmosphere","slide":36,"shape":"6","bookPage":"40"},{"text":"d the general weather conditions usually found in a particular place Correct answer: climate","slide":36,"shape":"8","bookPage":"40"},{"text":"e an increase in the Earth’s temperature because of pollution Correct answer: global warming","slide":37,"shape":"18","bookPage":"40"},{"text":"f to be likely to damage or harm something Correct answer: threaten","slide":37,"shape":"20","bookPage":"40"},{"text":"g all the living things in an area and the effect they have on each other and the environment Correct answer: ecosystem","slide":37,"shape":"6","bookPage":"40"},{"text":"h a source of energy like coal, gas and petroleum, formed inside the Earth millions of years ago Correct answer: fossil fuel","slide":38,"shape":"19","bookPage":"40"},{"text":"What has happened to the glacier?Possible answer: Much of the glacier has melted; the text describes water covering an area that used to be covered in ice and snow.","slide":51,"shape":"16","bookPage":"40"},{"text":"What do you think caused this change?Possible answer: A likely cause is a warmer climate.","slide":51,"shape":"18","bookPage":"40"},{"text":"What are some other places where a similar change is happening?Possible answer: The Arctic, the Alps and Alaska are examples discussed in the answer booklet.","slide":52,"shape":"16","bookPage":"40"},{"text":"How do you predict this kind of change will affect the world?Possible answer: Melting land ice can contribute to higher sea levels, and animals may lose habitat.","slide":52,"shape":"18","bookPage":"40"},{"text":"Read the article and number the main ideas in the order in which they appear: melting glaciers. Correct answer: 1","slide":67,"shape":"15","bookPage":"42"},{"text":"Read the article and number the main ideas in the order in which they appear: changing ecosystems. Correct answer: 2","slide":67,"shape":"17","bookPage":"42"},{"text":"Read the article and number the main ideas in the order in which they appear: causes of climate change. Correct answer: 3","slide":67,"shape":"6","bookPage":"42"},{"text":"Read the article and number the main ideas in the order in which they appear: solution to the problem. Correct answer: 4","slide":68,"shape":"16","bookPage":"42"},{"text":"Since 1900, global temperatures have gone up by around 1.0 °C.","slide":81,"shape":"15","bookPage":"42"},{"text":"Global increases in temperature could cause the extinction of 30% of land species.","slide":81,"shape":"17","bookPage":"42"},{"text":"Sea levels could rise by 30.5–122 cm by the end of the century.","slide":82,"shape":"15","bookPage":"42"},{"text":"Recently, over a third of the world’s mangrove forests have been destroyed.","slide":82,"shape":"17","bookPage":"42"},{"text":"Fifty percent of the Earth’s coral reefs have been lost in the last few decades.","slide":83,"shape":"18","bookPage":"42"},{"text":"Thirty-eight percent of the land on Earth is used for farming.","slide":83,"shape":"20","bookPage":"42"},{"text":"CO₂ levels are at their highest for 800,000 years.","slide":83,"shape":"6","bookPage":"42"},{"text":"Information\nDetail\n1 country where the Upsala Glacier is located\nArgentina\n2 name of sea route through the Arctic ice\nNorthwest Passage\n3 why forests are being cut down all over the world\nTo provide land for growing food\n4 medical problem caused by pollen\nasthma\n5 main chemicals responsible for climate change\ngreenhouse gases, such as methane and carbon dioxide","slide":97,"shape":"12","bookPage":"43"},{"text":"What was the author’s main purpose in writing this article? a inform the reader about causes and effects of global warming b describe changes in mangrove forests and coral reefs c persuade people to help reduce CO₂ levels by using renewable energy Correct answer: a — inform readers about causes and effects of global warming","slide":109,"shape":"15","bookPage":"43"},{"text":"Who is the intended audience for this article? a advanced science students b general adult readers c university professors Correct answer: b — general adult readers","slide":109,"shape":"17","bookPage":"43"},{"text":"What information in the article helped you choose your answer about purpose and audience?Possible answer: The article mainly explains the causes and effects of climate change. Coral reefs and mangroves are supporting examples. The final paragraph suggests action, but persuasion is not the main purpose of the whole article. The explanations are accessible to general readers.","slide":111,"shape":"14","bookPage":"43"},{"text":"11. Paragraph A\nAnswer: ii","slide":114,"shape":"5","bookPage":null},{"text":"12. Paragraph B\nAnswer: vii","slide":114,"shape":"8","bookPage":null},{"text":"Why are trees important for the environment?Possible answer: Trees absorb carbon dioxide, release oxygen and provide habitats.","slide":120,"shape":"19","bookPage":"44"},{"text":"Why do people cut down trees?Possible answer: People use wood for fuel or construction and clear land for farming.","slide":120,"shape":"21","bookPage":"44"},{"text":"What will happen if we destroy too many trees?Possible answer: Habitats may be lost, soil may erode and climate change may become worse.","slide":121,"shape":"20","bookPage":"44"},{"text":"The Amazon rainforest in South America receives 200 to 600 cm of rain every year.","slide":131,"shape":"14","bookPage":"44"},{"text":"The ground is already very wet, so it cannot absorb any more rain.","slide":131,"shape":"16","bookPage":"44"},{"text":"In this part of the country, people grow corn and wheat, so most jobs are in farming.","slide":132,"shape":"14","bookPage":"44"},{"text":"The city will have to be rebuilt after storms caused the destruction of many homes and businesses.","slide":132,"shape":"16","bookPage":"44"},{"text":"Sunburn is one harmful effect of too much sun on sensitive skin.","slide":133,"shape":"17","bookPage":"44"},{"text":"The side of the mountain looks brown and bare after many years of logging in the forests.","slide":133,"shape":"19","bookPage":"44"},{"text":"The government announced plans for the construction of a new bridge and major highway.","slide":133,"shape":"6","bookPage":"44"},{"text":"Forests are important because they produce (1) oxygen and (2) absorb CO₂.","slide":155,"shape":"18","bookPage":"46"},{"text":"They also provide a natural (3) habitat / home for many plants and animals.","slide":155,"shape":"20","bookPage":"46"},{"text":"Deforestation, that is, the (4) destruction of forests, is happening all over the world.","slide":156,"shape":"18","bookPage":"46"},{"text":"People cut down trees and use them for (5) fuel and as building material.","slide":156,"shape":"20","bookPage":"46"},{"text":"However, the main cause of deforestation is the increase in both commercial and local (6) farming.","slide":157,"shape":"18","bookPage":"46"},{"text":"These negative effects include soil (7) erosion, loss of (8) biodiversity and (9) climate change.","slide":157,"shape":"20","bookPage":"46"},{"text":"In Indonesia, trees are cut down to make way for olive oil plantations. False. Trees are cut down to make way for palm oil plantations.","slide":168,"shape":"18","bookPage":"46"},{"text":"One cause of deforestation is the use of wood for heat and cooking. True.","slide":168,"shape":"20","bookPage":"46"},{"text":"There has been more deforestation in Brazil than any other country. Does not say.","slide":168,"shape":"6","bookPage":"46"},{"text":"Deforestation protects future sources of food and medicine. False. Deforestation destroys future sources of food and medicine.","slide":168,"shape":"8","bookPage":"46"},{"text":"When temperatures increase, the rainforests become drier. True.","slide":169,"shape":"18","bookPage":"46"},{"text":"Farming causes a decrease in biodiversity. Does not say.","slide":169,"shape":"20","bookPage":"46"},{"text":"How do you think erosion leads to floods?Possible answer: When soil is damaged or lost, less rain may be absorbed and more water can flow over the land, contributing to floods.","slide":180,"shape":"19","bookPage":"46"},{"text":"How does deforestation reduce future sources of food and medicine?Possible answer: When plants and animals lose their habitats, species may disappear. This can remove sources of food and potential medicines.","slide":180,"shape":"21","bookPage":"46"},{"text":"Why are rainforests sometimes called the ‘lungs of the planet’?Possible answer: The phrase refers to forests exchanging gases with the atmosphere: they absorb CO₂ and release oxygen.","slide":181,"shape":"20","bookPage":"46"},{"text":"The most serious issue which threatens the environment is climate change.","slide":192,"shape":"14","bookPage":"47"},{"text":"Experts predict that there will not be enough fresh water in the future.","slide":192,"shape":"16","bookPage":"47"},{"text":"Pollution and climate change are the consequences of human activity.","slide":193,"shape":"17","bookPage":"47"},{"text":"Fortunately, we are seeing a trend where people recycle more and use less packaging.","slide":193,"shape":"19","bookPage":"47"},{"text":"Constant logging has left dry soil and bare land.","slide":194,"shape":"17","bookPage":"47"},{"text":"The annual rate of species loss in the rainforest is nearly 50,000 — that’s 135 plant, animal and insect species each day!","slide":194,"shape":"19","bookPage":"47"},{"text":"The biggest challenge we face is to protect the planet.","slide":194,"shape":"6","bookPage":"47"},{"text":"Human activity contributes to climate change.","slide":194,"shape":"8","bookPage":"47"},{"text":"carbon dioxide","slide":196,"shape":"17","bookPage":"48"},{"text":"greenhouse gases","slide":196,"shape":"18","bookPage":"48"},{"text":"natural resource","slide":196,"shape":"19","bookPage":"48"},{"text":"power plant","slide":196,"shape":"5","bookPage":"48"},{"text":"renewable energy","slide":196,"shape":"6","bookPage":"48"},{"text":"sea level","slide":196,"shape":"7","bookPage":"48"},{"text":"tropical rainforests","slide":196,"shape":"8","bookPage":"48"},{"text":"In my town, about 70% of the electricity comes from a power plant which uses coal for energy.","slide":199,"shape":"15","bookPage":"48"},{"text":"Carbon dioxide and methane are examples of greenhouse gases.","slide":199,"shape":"17","bookPage":"48"},{"text":"Scientists predict that an increase in the sea level will cause flooding in cities near the ocean.","slide":200,"shape":"15","bookPage":"48"},{"text":"Trees absorb carbon dioxide and give off oxygen.","slide":200,"shape":"17","bookPage":"48"},{"text":"Many countries are replacing fossil fuels with renewable energy sources, like wind and solar.","slide":201,"shape":"18","bookPage":"48"},{"text":"Fresh water is the most precious natural resource on Earth.","slide":201,"shape":"20","bookPage":"48"},{"text":"Thousands of unique plants, animals, birds and insects live in the tropical rainforests of South America and Southeast Asia.","slide":201,"shape":"6","bookPage":"48"},{"text":"In this imagined town, factories burn fossil fuels for energy. As a result, the air becomes polluted near homes. The town could encourage cleaner sources of energy.","slide":206,"shape":"6","bookPage":null},{"text":"A long dry period has reduced the water available to this imagined village. Farmers cannot water all their crops. The village could collect rainwater when it returns.","slide":206,"shape":"9","bookPage":null},{"text":"1. The group investigated earlier tree losses before beginning its planting trial.\nAnswer: TRUE","slide":211,"shape":"5","bookPage":null},{"text":"2. The first planting weekend was planned for June.\nAnswer: NOT GIVEN","slide":211,"shape":"8","bookPage":null},{"text":"11. Paragraph A\nAnswer: vii","slide":214,"shape":"5","bookPage":null},{"text":"12. Paragraph B\nAnswer: vi","slide":214,"shape":"8","bookPage":null},{"text":"A dry season has left our imagined village with very little water. This crisis affects both homes and farms. The remaining supply is a shared resource. Residents could agree to use less water in their gardens.","slide":219,"shape":"6","bookPage":null},{"text":"Poor air quality is an environmental concern near the imagined town centre. Traffic may contribute to it. A team could count vehicles and measure air quality during the day. Their observations could help the council choose a response.","slide":220,"shape":"6","bookPage":null},{"text":"climate change","slide":233,"shape":"10","bookPage":"49"},{"text":"industrial logging","slide":233,"shape":"12","bookPage":"49"},{"text":"damage to animal habitats","slide":233,"shape":"14","bookPage":"49"},{"text":"farming by local people","slide":233,"shape":"16","bookPage":"49"},{"text":"heavy soil erosion and flooding","slide":233,"shape":"18","bookPage":"49"},{"text":"4  global warming","slide":241,"shape":"8","bookPage":"50"},{"text":"1  less rain","slide":241,"shape":"10","bookPage":"50"},{"text":"5  forests dry out","slide":241,"shape":"12","bookPage":"50"},{"text":"3  fires","slide":241,"shape":"14","bookPage":"50"},{"text":"2  more CO₂\nemissions","slide":241,"shape":"16","bookPage":"50"},{"text":"Using information from Reading 1 and Reading 2 and your own ideas, brainstorm the human causes and effects of climate change.Possible answer: Human causes include burning fossil fuels and deforestation; effects include global warming, melting glaciers, rising sea levels, habitat loss and more extreme weather.","slide":262,"shape":"11","bookPage":"50"},{"text":"forests become hot\nand dry","slide":265,"shape":"11","bookPage":"50"},{"text":"more forest fires","slide":265,"shape":"13","bookPage":"50"},{"text":"fewer living trees\nabsorb CO₂","slide":265,"shape":"15","bookPage":"50"},{"text":"more CO₂ remains in\nthe atmosphere","slide":265,"shape":"17","bookPage":"50"},{"text":"Global warming (1) leads to / causes / results in higher temperatures.","slide":269,"shape":"15","bookPage":"51"},{"text":"Global warming (2) leads to / causes / results in melting glaciers.","slide":269,"shape":"17","bookPage":"51"},{"text":"Melting glaciers are (3) caused by / due to / the result of higher temperatures.","slide":270,"shape":"15","bookPage":"51"},{"text":"Higher temperatures are (4) caused by / due to / the result of global warming.","slide":270,"shape":"17","bookPage":"51"},{"text":"Write a sentence about animal habitats using an expression of cause and effect.Possible answer: Deforestation causes the destruction of animal habitats.","slide":274,"shape":"16","bookPage":"51"},{"text":"Write a sentence about soil erosion using an expression of cause and effect.Possible answer: Soil erosion can lead to flooding.","slide":274,"shape":"18","bookPage":"51"},{"text":"Write a sentence about higher levels of CO₂ using an expression of cause and effect.Possible answer: Higher levels of CO₂ can result from forest fires.","slide":274,"shape":"6","bookPage":"51"},{"text":"Write a sentence about higher global temperatures using an expression of cause and effect.Possible answer: Higher global temperatures are caused by increased greenhouse gases.","slide":275,"shape":"19","bookPage":"51"},{"text":"Write a sentence about extreme weather, such as strong storms and heatwaves, using an expression of cause and effect.Possible answer: Global warming can lead to more extreme weather, such as strong storms and heatwaves.","slide":275,"shape":"21","bookPage":"51"},{"text":"Sea levels may rise because of melting glaciers.","slide":278,"shape":"15","bookPage":"52"},{"text":"In a warmer world, there are more fires because there is less rain.","slide":278,"shape":"17","bookPage":"52"},{"text":"Possible answer: Sea levels may rise because of global warming.","slide":283,"shape":"17","bookPage":"52"},{"text":"Possible answer: Loss of animal habitat and biodiversity is caused by deforestation.","slide":283,"shape":"19","bookPage":"52"},{"text":"In the paragraph, circle the main idea. Correct answer: Plastic water bottles hurt both people and the environment.","slide":288,"shape":"15","bookPage":"52"},{"text":"In the paragraph, cross out one sentence which does not support that idea. Correct answer: In the 1970s, the United States was the world’s biggest exporter of fossil fuels.","slide":288,"shape":"17","bookPage":"52"},{"text":"1 Find two supporting sentences and underline them.First: Plastic bottles contain two harmful chemicals: BPA and phthalates.Second: Plastic bottles hurt the environment.","slide":290,"shape":"15","bookPage":"53"},{"text":"2 What detail explains the first supporting sentence? Is this a fact, example or reason?Both types of chemicals can cause serious health problems in both adults and children. The writer presents this as a fact.","slide":290,"shape":"16","bookPage":"53"},{"text":"3 How do plastic bottles harm the environment? What details explain each effect?The bottles are made from petroleum, and transporting them requires an enormous amount of polluting fossil fuels. These are factual supporting details.","slide":290,"shape":"17","bookPage":"53"},{"text":"3 How do plastic bottles harm the environment? What details explain each effect?Most plastic bottles are not recycled. They end up in landfills, where they can take many decades to break down. These are factual supporting details.","slide":291,"shape":"19","bookPage":"53"},{"text":"Desertification is a process in which land becomes drier, losing bodies of water such as (1) lakes as well as wildlife and vegetation, particularly (2) trees.","slide":296,"shape":"15","bookPage":"54"},{"text":"Desertification has a number of causes, including (3) climate change, deforestation and damaging farming methods.","slide":296,"shape":"16","bookPage":"54"},{"text":"Desertification is a very serious problem in many regions of the Earth, especially poor parts of (4) Africa, Asia and the Middle East.","slide":296,"shape":"17","bookPage":"54"},{"text":"For instance, (5) the Gobi Desert in China is the fastest-growing desert in the world.","slide":297,"shape":"19","bookPage":"54"},{"text":"Another example is (6) northern Lebanon, where forests were destroyed in order to build cities.","slide":297,"shape":"20","bookPage":"54"},{"text":"Farmers in some dry areas plant leguminous plants like (7) peas and beans, which pull nitrogen from the air and make the soil richer.","slide":298,"shape":"19","bookPage":"54"},{"text":"Another method is (8) placing stones around the base of trees.","slide":298,"shape":"20","bookPage":"54"},{"text":"In this imagined region, factories use fossil fuels for electricity. As a result, more gases enter the atmosphere. This may contribute to climate change. The region should consider wind or solar power.","slide":302,"shape":"6","bookPage":null},{"text":"Gardens in this imagined town are watered at midday. Because the sun is strong, much water disappears quickly. Therefore, residents should water plants in the evening. This may save water during dry weeks.","slide":303,"shape":"6","bookPage":null}];
